// Set the 'approved_by' field to the name of the user who approved

function onClick() {

    //g_form.addInfoMessage('Making field Read Ony');

    g_form.setReadOnly('u_target_app', true);
    g_form.setReadOnly('field_from_task',true );

    g_form.setReadOnly('expected_value', true);
    g_form.setReadOnly('points', true);
    g_form.setReadOnly('u_fff', true);
    // Use gsftSubmit to call the server-side script
    gsftSubmit(null, g_form.getFormElement(), 'enable_config');

}
if (typeof window == 'undefined')
    approveTask();

function approveTask() {

    current.enabled = true;
    current.approved_by = gs.getUserID(); // Get the full name of the current user

    // Set the 'approved_at' field to the current date and time
    current.approved_time = new GlideDateTime(); // Set the current date and time

    // Update the record
    current.update();
    action.setRedirectURL(current);
}
